def invoke_replay_ls(directory, topology, scenario, seed=0):
    topo_path = write_topology(directory, topology)
    scenario_path = write_scenario(directory, scenario)
    return run_cli(
        ["replay-ls", str(topo_path), str(scenario_path)], seed=seed
